import sys
from collections import deque

def main():
    input = sys.stdin.readline
    L, C = map(int, input().split())
    grid = [input().strip() for _ in range(L)]

    sr = sc = -1
    for i in range(L):
        j = grid[i].find('o')
        if j != -1:
            sr, sc = i, j
            break

    visited = [[False] * C for _ in range(L)]
    q = deque([(sr, sc, 0)])
    visited[sr][sc] = True

    ans = (sr, sc, 0)
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        r, c, d = q.popleft()
        if d > ans[2]:
            ans = (r, c, d)

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < L and 0 <= nc < C:
                if not visited[nr][nc] and grid[nr][nc] == 'H':
                    visited[nr][nc] = True
                    q.append((nr, nc, d + 1))

    print(ans[0] + 1, ans[1] + 1)

if __name__ == "__main__":
    main()
